//! One-time session tokens for the loopback endpoint.
//!
//! The token is the only credential a request to the endpoint carries besides
//! its origin headers (see `serve.rs`), and it plays AutoFirma's role: the
//! page learns an `idsession` at launch time (`afirma://websocket?…&idsession=`,
//! checked per message in `AfirmaWebSocketServerV4Sup.onMessage`) and must put
//! it in every message. Ours is generated by the *server* (a random id on the
//! same `[a-z0-9]` alphabet and inside the same ≤20-character limit AutoFirma's
//! own parser enforces, filling that budget: 36^20 ≈ 2^103.4, which is what
//! those characters hold — 128 bits would take 25 of them), handed to whoever
//! opened us — out of band, exactly like the port is — and consumed by its
//! first request. A page that never learned it cannot ask; a second request
//! with the same id is a replay and gets refused.

use getrandom::fill;

/// The longest session id AutoFirma's protocol accepts: `MAX_ID_LENGTH = 20`
/// in `UrlParameters`, because it doubles as a file name. The token plays that
/// id, so it stays inside the limit and uses all of it — every extra character
/// of a uniform `[a-z0-9]` string is 5.17 bits.
const TOKEN_LEN: usize = 20;

const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789";

/// The first byte value that is NOT a whole multiple of the alphabet's size:
/// 252 = 36 × 7. Bytes from here up are rejected instead of folded, because
/// `byte % 36` would make the first four symbols (the bytes 252..=255 folded
/// onto them) likelier than the other thirty-two by one in 256 — a bias the
/// token's own entropy claim could not survive (review 04, B-6: what was
/// written there was not what the code did, twice over).
const REJECT_FROM: u8 = 252;

/// One symbol for a random byte, or `None` if the byte must be redrawn. Below
/// `REJECT_FROM` every symbol is hit exactly seven times over the 252 values,
/// which is the uniformity the whole construction rests on.
fn symbol_from(byte: u8) -> Option<char> {
    if byte >= REJECT_FROM {
        return None;
    }
    Some(ALPHABET[(byte % ALPHABET.len() as u8) as usize] as char)
}

fn random_token() -> String {
    let mut token = String::with_capacity(TOKEN_LEN);
    let mut bytes = [0u8; 32];
    // getrandom's fill does not return until the OS entropy pool answers or
    // the process is killed for asking; neither can be handled better than by
    // letting it do its job. Rejection makes the number of draws variable and
    // bounded (1/16 of draws are discarded), never unbounded.
    while token.len() < TOKEN_LEN {
        fill(&mut bytes).expect("the operating system's random source must answer");
        for byte in bytes {
            if let Some(symbol) = symbol_from(byte) {
                token.push(symbol);
                if token.len() == TOKEN_LEN {
                    break;
                }
            }
        }
    }
    token
}

/// A small table of live session tokens. `take` consumes one, atomically: the
/// window between check and use is zero bytes of logic wide, which is the
/// only way a one-time token is actually one-time under a concurrent server.
#[derive(Debug)]
pub struct TokenStore {
    inner: std::sync::Mutex<Vec<String>>,
}

impl Default for TokenStore {
    fn default() -> Self {
        Self::new()
    }
}

impl TokenStore {
    pub fn new() -> Self {
        TokenStore {
            inner: std::sync::Mutex::new(Vec::new()),
        }
    }

    /// Creates a fresh session id and hands it to the caller (the CLI's
    /// stdout, or the loopback server's own owner). A poisoned lock — some
    // other connection panicked mid-update — means the table may hold
    // garbage, so minting from it is refused rather than trusted.
    pub fn issue(&self) -> String {
        let mut guard = self
            .inner
            .lock()
            .expect("the token table must not stay poisoned: a handler panicked while holding it");
        let token = random_token();
        guard.push(token.clone());
        token
    }

    /// True if `presented` is a live session id, consuming it. Comparison is
    /// exact string equality; the ids are not secret-after-use, so constant
    /// time buys nothing here — the table lookup itself does not leak whether
    /// an id exists beyond timing that scales with live sessions (at most a
    // handful).
    //
    // Consumption means a PRESENTED token, and by the endpoint's own order of
    // operations (serve.rs: the `take` runs after head *and* body have fully
    // arrived) it happens before any header rule is judged. So even a POST
    // that dies at bad-origin spent its one-time credential — a caller whose
    // answer was lost in transit must never re-present one, and tests of the
    // one-shot property need to see both halves: `take` grants once, then
    // never again, whatever happened to the request that consumed it.
    pub fn take(&self, presented: &str) -> bool {
        if presented.is_empty() || presented.len() > 20 {
            return false;
        }
        let mut guard = match self.inner.lock() {
            Ok(guard) => guard,
            // A poisoned table is an empty one for the purposes of granting
            // access: nothing in it can be trusted any more.
            Err(_) => return false,
        };
        if let Some(pos) = guard.iter().position(|t| t == presented) {
            guard.remove(pos);
            true
        } else {
            false
        }
    }

    pub fn len(&self) -> usize {
        self.inner.lock().map(|g| g.len()).unwrap_or(0)
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Review 04, B-6: the number in this file's comments was not what the code
    /// did — 16 characters of a 36-symbol alphabet are ≈82.7 bits, not 128 —
    /// and the fold `byte % 36` was not uniform either. Both halves are pinned
    /// here, deterministically: no sampling, so the test cannot flake.
    #[test]
    fn every_symbol_is_reachable_exactly_seven_times_below_the_rejection_line() {
        let mut counts = std::collections::BTreeMap::new();
        for byte in 0..REJECT_FROM {
            let symbol = symbol_from(byte).expect("a byte below the line always maps");
            *counts.entry(symbol).or_insert(0u32) += 1;
        }
        assert_eq!(counts.len(), ALPHABET.len(), "every symbol is reachable");
        assert!(
            counts.values().all(|n| *n == 7),
            "252 = 36 x 7: each of the 36 symbols must be drawn the same number \
             of times, which is exactly what `% 36` did not do: {counts:?}"
        );
        // The four remaining byte values would fold onto symbols that already
        // have their seven draws; they are redraws instead.
        for byte in REJECT_FROM..=u8::MAX {
            assert_eq!(symbol_from(byte), None, "{byte} must be a redraw");
        }
    }

    #[test]
    fn a_token_fills_the_protocols_id_limit_and_is_spent_once() {
        let store = TokenStore::new();
        assert!(store.is_empty());
        let token = store.issue();
        assert_eq!(token.len(), TOKEN_LEN);
        assert!(
            token.len() <= 20,
            "UrlParameters' MAX_ID_LENGTH, which this id plays"
        );
        assert!(
            token
                .bytes()
                .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit())
        );
        assert_eq!(store.len(), 1);
        assert!(store.take(&token));
        assert!(!store.take(&token), "a token is spent by its first request");
        assert!(store.is_empty());
        // Minting is not returning a constant. Not a randomness test — that is
        // the OS's entropy source's job, and `symbol_from` above is where the
        // distribution claim is checkable at all.
        assert_ne!(store.issue(), store.issue());
    }
}
